package com.ssk.kiosk.controller;import com.ssk.kiosk.dto.*;import com.ssk.kiosk.repo.*;import com.ssk.kiosk.service.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor class ApiController{private final VisitorCategoryRepository categories;private final HostRepository hosts;private final VisitApplicationRepository apps;private final AuditLogRepository audits;private final GatePassService service;@PostMapping("/kiosk/sessions") Map<String,Object> session(){return Map.of("sessionId",UUID.randomUUID(),"timeoutSeconds",180);}@GetMapping("/kiosk/categories") Object categories(){return categories.findAll().stream().map(c->new CategoryDto(c.getId(),c.getCode(),c.getNameEn(),c.getNameAr(),c.isApprovalRequired())).toList();}@PostMapping("/kiosk/sessions/{sessionId}/application") ApplicationResponse app(@PathVariable UUID sessionId,@Valid @RequestBody ApplicationRequest r){return service.create(r);}@GetMapping("/hosts/search") Object hosts(@RequestParam(defaultValue="") String q){return hosts.findTop20ByFullNameContainingIgnoreCaseOrEmployeeIdContainingIgnoreCaseOrDepartmentContainingIgnoreCaseOrEmailContainingIgnoreCaseOrPhoneContainingIgnoreCase(q,q,q,q,q).stream().map(h->new HostDto(h.getId(),h.getEmployeeId(),h.getFullName(),h.getDepartment(),h.getEmail(),h.getPhone())).toList();}@PostMapping("/passes/validate") ValidationResponse validate(@Valid @RequestBody ValidateRequest r){return service.validate(r);}@PostMapping("/passes/{id}/check-in") ApplicationResponse in(@PathVariable UUID id,@RequestBody CheckRequest r){return service.checkIn(id,r);}@PostMapping("/passes/{id}/check-out") ApplicationResponse out(@PathVariable UUID id,@RequestBody CheckRequest r){return service.checkOut(id,r);}@GetMapping("/admin/dashboard") Object dashboard(){return Map.of("expectedToday",apps.count(),"pendingApprovals",0,"visitorsInside",0,"recentActivities",audits.findAll(PageRequest.of(0,10)).getContent());}@GetMapping("/admin/applications") Object list(){return apps.findAll().map(GatePassService::map);}@GetMapping("/applications/{id}") ApplicationResponse get(@PathVariable UUID id){return apps.findById(id).map(GatePassService::map).orElseThrow();}}
